import React, { useState } from 'react';
import '../styles/LoginPage.css'; // CSS 파일 import

const LoginPage = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log('Input:', { email, password });
  };

  return (
    <div className="login-container">
      <h1 className="login-title">Issue Tracker</h1>
      
      <form onSubmit={handleSubmit} className="login-form">
        <input
          type="email"
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          className="login-input"
          required
        />
        <input
          type="password"
          placeholder="Password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          className="login-input"
          required
        />
        <button type="submit" className="login-button">
          LOGIN
        </button>
      </form>

      <div className="login-links">
        <a href="#forgot" className="login-link">Forgot password?</a>
        <p className="login-text">No account? <a href="#contact" className="login-link">Contact admin</a></p>
      </div>
    </div>
  );
};

export default LoginPage;
